-- NIL Intelligence Network update, part 02 of 06: seed data (starts by emptying the seed tables; identity columns restart).
begin;
do $$ declare t text; begin
  select string_agg(format('public.%I', tablename), ', ') into t from pg_tables where schemaname = 'public' and tablename <> 'schema_migrations';
  execute 'truncate table ' || t || ' restart identity cascade';
end $$;
commit;
select 'part 02 applied' as result;
