insert into states (code, name, slug) values ('FL', 'Florida', 'florida');
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('ncaa', 'National Collegiate Athletic Association', 'NCAA', 'national_association', 'https://www.ncaa.org/', 'Sets Division I rules, including Bylaw Article 22 on name, image and likeness.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('college-sports-commission', 'College Sports Commission', 'College Sports Commission', 'enforcement_body', 'https://www.collegesportscommission.org/', 'Runs NIL Go, the clearinghouse that reviews third-party NIL deals for Division I athletes, and enforces the House settlement rules.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('florida-legislature', 'Florida Legislature', 'Florida law', 'state_legislature', 'http://www.leg.state.fl.us/', 'Enacts Florida Statutes, including section 1006.74 on intercollegiate athlete compensation.', (select id from states where code = 'FL'));
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('florida-board-of-governors', 'Florida Board of Governors', 'Florida Board of Governors', 'state_agency', 'https://www.flbog.edu/', 'Regulates the State University System, including Regulation 6.022 on intercollegiate athletes.', (select id from states where code = 'FL'));
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('fhsaa', 'Florida High School Athletic Association', 'FHSAA', 'state_association', 'https://fhsaa.com/', 'Governs interscholastic athletics for its member high schools in Florida. Bylaw 9.9 covers amateurism and NIL.', (select id from states where code = 'FL'));
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('sec', 'Southeastern Conference', 'SEC', 'conference', 'https://www.secsports.com/', 'Athletic conference.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('acc', 'Atlantic Coast Conference', 'ACC', 'conference', 'https://theacc.com/', 'A separate ACC NIL rule or NIL guidance page for members: Not located in the public sources reviewed as of October 3, 2026. Searches of theacc.com found only a July 26, 2024 joint statement on the House settlement filing, which describes national terms, and unrelated eligibility news. No ACC-specific NIL rule was recorded.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('american', 'American Conference', 'American', 'conference', 'https://theamerican.org/', 'The American publishes one sentence on its About page about league-wide minimum investment and revenue sharing protocols. A conference NIL rule, NIL guidance page or the official release with the terms: Not located in the public sources reviewed as of October 3, 2026.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('big-12', 'Big 12 Conference', 'Big 12', 'conference', 'https://big12sports.com/', 'NIL rules for members were not located in the public sources reviewed as of October 3, 2026. The public Big 12 compliance page has no NIL text and its documents database is behind a login. News reports from May 2026 say all Big 12 schools agreed to sign College Sports Commission participation agreements, but no official Big 12 page for this was found.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('conference-usa', 'Conference USA', 'CUSA', 'conference', 'https://conferenceusa.com/', 'NIL rules for members were not located in the public sources reviewed as of October 3, 2026. The Conference USA compliance page has no NIL text and no public handbook or bylaws link was found on the site navigation.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('swac', 'Southwestern Athletic Conference', 'SWAC', 'conference', 'https://swac.org/', 'The only SWAC-published NIL-related item found was the June 16, 2025 spring meetings recap saying all twelve members opted in to the House settlement. No SWAC NIL policy, NIL page or member NIL rule was found in the swac.org site menu links checked. Not located in the public sources reviewed as of October 3, 2026.', NULL);
insert into governing_bodies (slug, name, short_name, body_type, website_url, description, state_id) values ('asun', 'Atlantic Sun Conference', 'ASUN', 'conference', 'https://asunsports.org/', 'No ASUN NIL rule for members was found. The ASUN published a December 2023 release about a preferred partnership with BuzzU, described as ''a leading data analytics firm in the name, image and likeness (NIL) industry''. That release is older than the House settlement and its current status is unknown. No official ASUN statement on House settlement opt-in was located. Not located in the public sources reviewed as of October 3, 2026.', NULL);
insert into school_districts (slug, name, county, website_url, nces_district_id, state_id) values ('seminole-county-public-schools', 'Seminole County Public Schools', 'Seminole County', 'https://www.scps.k12.fl.us/', '1201710', (select id from states where code = 'FL'));
