insert into sources (slug, title, url, organization, source_type, published_on, notes, governing_body_id, retrieved_on, is_primary) values ('fhsaa-bylaw-9-9-sbe-2024', 'FHSAA Bylaw 9.9 Amateurism, text presented to the State Board of Education', 'https://www.fldoe.org/core/fileparse.php/20758/urlt/5.2.pdf', 'Florida Department of Education (text of FHSAA Bylaw 9.9)', 'board_document', '2024-07-24', 'Bylaw text as presented for ratification. Section numbers for penalties changed after the September 2024 amendment (9.9.5 became 9.9.6). Compare against the 2026-27 FHSAA Handbook before marking verified.', (select id from governing_bodies where slug = 'fhsaa'), '2026-10-03', TRUE);
